// POST /webhook/nl2sql  { "question": "..." }
const body = $input.first().json.body || $input.first().json || {};
const question = String(body.question || '').trim();

return [{ json: { question } }];

// Stage: turn the live information_schema rows into a compact schema
// description, then build the actual prompt asking the LLM to write SQL.
// Grounding the prompt in the REAL current schema (not a hardcoded one)
// is what keeps this working if the database changes later.
const rows = $input.all().map((i) => i.json);
const byTable = {};
for (const r of rows) {
  byTable[r.table_name] = byTable[r.table_name] || [];
  byTable[r.table_name].push(`${r.column_name} ${r.data_type}`);
}
const schema = Object.entries(byTable)
  .map(([table, cols]) => `${table}(${cols.join(', ')})`)
  .join('\n');

const question = $('Read Question').first().json.question;

const prompt = `You are a PostgreSQL expert. Given this schema:\n\n${schema}\n\n` +
  'Write a single read-only SQL query that answers the question below.\n' +
  'Rules:\n' +
  '- Only a SELECT statement. Never INSERT/UPDATE/DELETE/DROP/ALTER/TRUNCATE.\n' +
  '- Exactly one statement.\n' +
  '- Add LIMIT 100 if the result could be large and there is no LIMIT already.\n' +
  '- Return ONLY the raw SQL - no markdown fences, no explanation.\n\n' +
  `Question: ${question}`;

return [{ json: { question, schema, prompt } }];

const res = $json;
let sql = res.candidates?.[0]?.content?.parts?.[0]?.text || '';
sql = sql.replace(/```sql/gi, '').replace(/```/g, '').trim();
sql = sql.replace(/;\s*$/, '');

const question = $('Build SQL Prompt').first().json.question;

return [{ json: { question, sql } }];

// Safety gate before anything the LLM wrote touches a real database:
// only a single SELECT/CTE statement, no destructive keywords, no
// statement-chaining via semicolons.
const sql = $json.sql;
const normalized = sql.trim().toLowerCase();

const isReadOnly = normalized.startsWith('select') || normalized.startsWith('with');
const hasForbidden = /\b(insert|update|delete|drop|alter|truncate|grant|revoke|create)\b/i.test(sql);
const singleStatement = (sql.match(/;/g) || []).length === 0;

const safe = isReadOnly && !hasForbidden && singleStatement;

return [{ json: { ...$json, safe } }];

const rows = $input.all().map((i) => i.json);
const question = $('Guard: Read-Only Only').first().json.question;
const sql = $('Guard: Read-Only Only').first().json.sql;

const prompt = `Question: ${question}\nSQL used: ${sql}\nResult rows (JSON): ${JSON.stringify(rows).slice(0, 4000)}\n\n` +
  'Answer the question in 2-3 plain-English sentences using only these rows. Cite concrete numbers.';

return [{ json: { question, sql, rows, prompt } }];

const res = $json;
const answer = res.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
const prev = $('Build Summary Prompt').first().json;

return [{
  json: {
    ok: true,
    question: prev.question,
    sql: prev.sql,
    rowCount: prev.rows.length,
    rows: prev.rows,
    answer,
  }
}];

return [{
  json: {
    ok: false,
    question: $json.question,
    blockedSql: $json.sql,
    reason: 'The generated SQL failed the read-only safety check and was not executed.',
  }
}];
